-- Class notes synopsis batch 20: Pennyroyal through Prince Seng

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Pennyroyal</strong> contains pulegone; <strong>the essential oil and hydrosol are toxic and hazardous.</strong>$$
WHERE id = 135;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Peppermint</strong> (Mentha piperita) is a <strong>diaphoretic</strong>, <strong>carminative</strong>, <strong>antiemetic</strong>, <strong>antispasmodic</strong>, and <strong>antimicrobial</strong> volatile oil plant; a <strong>cooling</strong> herb for hot constitution and an awesome flavoring agent. Primary indications: <strong>nausea</strong>, <strong>bloating</strong>, <strong>gas</strong>, and digestive discomfort - best taken as tea after eating; carminative for <strong>hypochlorhydria</strong>. Antispasmodic for <strong>spasmodic diarrhea</strong> alongside <a href="?herb=76"><strong>Fennel</strong></a>, <a href="?herb=136"><strong>Catnip</strong></a>, <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=124"><strong>Ginger</strong></a>. Antiemetic for <strong>influenza nausea</strong> with <a href="?herb=124"><strong>Ginger</strong></a>. EO (1-2 drops in 1 T honey) for minor and <strong>severe burns</strong>. Part of Urinary System Support glycerite with <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=22"><strong>Burdock</strong></a>, and <a href="?herb=1648"><strong>Dandelion</strong></a> leaf - purpose: move water and remove waste. Colic tincture (1 part) with <a href="?herb=122"><strong>Dandelion</strong></a> root, <a href="?herb=78"><strong>Licorice</strong></a>, and <a href="?herb=76"><strong>Fennel</strong></a>. Mint (peppermint or <a href="?herb=2607"><strong>Spearmint</strong></a>) in traditional African American glycerine syrup - interchangeable with <a href="?herb=134"><strong>Lemon Balm</strong></a>. In Four Thieves Vinegar: antimicrobial. For <strong>GI issues in pets</strong>: cooling herb alongside <a href="?herb=84"><strong>Chamomile</strong></a>. <strong>For pregnancy (morning sickness, headaches, digestive symptoms, nausea, stomach cramps): use as tea or glycerite - avoid essential oil in pregnancy.</strong> Good combo with <a href="?herb=84"><strong>Chamomile</strong></a> for pregnancy nausea; use if Chamomile is insufficient for stomach cramps.$$
WHERE id = 55;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Periwinkle</strong> is a <strong>uterine tonic</strong> and <strong>astringent</strong>; grouped with <a href="?herb=72"><strong>Blue Cohosh</strong></a> and <a href="?herb=25"><strong>Black Cohosh</strong></a> as uterine tonics and astringents.$$
WHERE id = 157;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Pine Needles</strong> (evergreen/pine oil; needles and resin) are <strong>anti-inflammatory</strong>, <strong>antibacterial</strong>, <strong>antimicrobial</strong>, <strong>lymphatic</strong>, and <strong>anti-tumor</strong>; a drying herb. <strong>Bronchodilator</strong> for <strong>asthma</strong> alongside <a href="?herb=104"><strong>Osha</strong></a> and <a href="?herb=132"><strong>Lobelia</strong></a>. Steam inhalation for <strong>bronchitis</strong> alongside <a href="?herb=101"><strong>Eucalyptus</strong></a> and <a href="?herb=59"><strong>Thyme</strong></a> - volatile oil plants that break up congestion. Antimicrobial for wound wash and cuts and open wounds (applied externally). Good for <strong>pain</strong> and <strong>arthritic joints</strong>. Lymphatic support in cancer care.$$
WHERE id = 2643;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Plantain</strong> (Plantago major / lanceolata) is a <strong>vulnerary</strong>, <strong>demulcent</strong>, <strong>astringent</strong> (tannin-rich), <strong>anti-inflammatory</strong>, <strong>antimicrobial</strong>, <strong>drawing agent</strong>, and <strong>relaxing expectorant</strong> - one of the essential herbs of the Middle Ages in western Europe; a superstar for the <strong>GI</strong>. Dual-action for GI repair: contains both tannins (astringent) and mucilage (demulcent); cooling, moistening, and relaxing in digestive formulas; specific for signs of laxness and leaky tissues that secrete fluids such as blood or mucus; for <strong>diarrhea</strong> (especially smelly diarrhea; clears damp heat) and <strong>leaky gut</strong>. Formula for gut lining repair: Plantain, <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=45"><strong>Marshmallow</strong></a> root - grind together, powder marshmallow EP into applesauce before every meal; pectin aids absorption, seals tight junctions, especially protective before coffee; great for healing ulcers. Colon Rescue for diarrhea: <a href="?herb=92"><strong>Slippery Elm</strong></a>, <a href="?herb=45"><strong>Marshmallow</strong></a>, Plantain, <a href="?herb=78"><strong>Licorice</strong></a>. Gut health infusion: Plantain + <a href="?herb=70"><strong>Calendula</strong></a>; tonifier for intestines; internal use for chronic digestive issues and GI inflammation. Repair tea blend with <a href="?herb=151"><strong>Horsetail</strong></a> and <a href="?herb=70"><strong>Calendula</strong></a> for respiratory membrane support in chronic asthma. Lung tonic alongside <a href="?herb=61"><strong>Mullein</strong></a>, <a href="?herb=11"><strong>Reishi Mushroom</strong></a>, <a href="?herb=9"><strong>Siberian Ginseng</strong></a>. Relaxing expectorant alongside <a href="?herb=61"><strong>Mullein</strong></a> and <a href="?herb=54"><strong>Elecampane</strong></a>. First aid herb like <a href="?herb=44"><strong>Yarrow</strong></a>: pulls out bee stings with tannins, draws out splinters; excellent topically for insect bites, foreign bodies, minor wounds, bites, rashes, stings, and skin inflammation - preparations: salve, compress, tincture, liniment, or plantain oil. Plantain + <a href="?herb=81"><strong>St. John's Wort</strong></a> in gauze after dental procedures in pets: good for gum irritation or inside cheek. Wound wash vulnerary alongside <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=82"><strong>Lavender</strong></a>, <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=2437"><strong>Self Heal</strong></a>, <a href="?herb=88"><strong>Chickweed</strong></a>, <a href="?herb=81"><strong>St. John's Wort</strong></a> (steep 45 min to 1 hour, strain well, put in thermos). Perineal wash with <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=850"><strong>Rose</strong></a>, <a href="?herb=44"><strong>Yarrow</strong></a>.$$
WHERE id = 85;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Poke Root</strong> (Phytolacca americana) is a powerful <strong>lymphagogue</strong>, <strong>anticarcinogenic</strong>, <strong>circulatory stimulant</strong>, and <strong>nervine</strong>; all parts used in the African American Materia Medica (leaves, root, berries). Specific Poke Root picture: <strong>thyroid hypofunction</strong> with fluid retention and immune depression, puffy face and ankles, chronic hard inflamed neck nodes, <strong>eczema</strong>, cracks on the sides of the mouth. Pairs: fibrocystic acute <strong>breast disease</strong> + <a href="?herb=981"><strong>Red Root</strong></a>; acute <strong>mastitis</strong> + <a href="?herb=981"><strong>Red Root</strong></a> + <a href="?herb=2635"><strong>Cotton Root Bark</strong></a>; bacterial infections in feeble individuals + <a href="?herb=26"><strong>Echinacea</strong></a> + <a href="?herb=23"><strong>Wild Indigo</strong></a>. For <strong>cancer</strong> care: anticarcinogenic - inhibits, mitigates, prevents, and can help cure cancer; important for lymphatic flow; used aggressively alongside <a href="?herb=288"><strong>Black Walnut</strong></a> leaf in early cancer stages; useful for tumor involvement; in anti-cancer formula 2 (more intense, used after formula 1); breaks up tumors and scar tissue in tea for chemo support; listed as nervine in cancer support. For <strong>metabolic disruptions</strong>, lipid issues, and lymphatic stimulation. For <strong>rheumatoid arthritis</strong>: lymph circulation (low dose). For <strong>eczema</strong> as lymphatic: start 1 drop, then 2, up to 5 - low and slow to not cause a flare. For <strong>common cold</strong>: lymphatic support - small doses only. Liver deficiency: only in extreme cases or as small part of formula to stimulate liver metabolism. Female and male <strong>reproductive deficiency</strong>: circulatory stimulant (little poke). Lymph/Immune deficiency: lymphagogue. <strong>Drop dose or low dose only - caustic; start low and slow; can give rashes as waste moves out. Dose: fresh 2-5 drops, dry 5-15 drops, up to 3x/day; 2-3 drops per dose in formula. Poisonous: leaves edible only when berry is still white, not yet red.</strong>$$
WHERE id = 35;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Pomegranate</strong> is documented in the African American Materia Medica as part of the 108 recorded species.$$
WHERE id = 2753;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Prickly Ash</strong> is a <strong>pungent</strong>, spicy <strong>warming</strong> <strong>circulatory stimulant</strong> and <strong>vasodilator</strong> for blood and lymph. Specifically indicated for <strong>Raynaud's syndrome</strong>. Dose: 1-2 mL twice daily for circulatory and digestive stimulation. Circulatory stimulant for cold and wet constitution alongside <a href="?herb=1009"><strong>Dong Quai</strong></a>, <a href="?herb=47"><strong>Cayenne</strong></a>, <a href="?herb=35"><strong>Poke Root</strong></a> (lymph), <a href="?herb=70"><strong>Calendula</strong></a> (lymph), <a href="?herb=1248"><strong>Ocotillo</strong></a> (lymph). Enhances circulation to <strong>hair follicles</strong> alongside <a href="?herb=2229"><strong>Gotu Kola</strong></a> for hair strength. Upper GI deficiency: functional digestive stimulant. Liver deficiency: stimulates arterial circulation to the liver. Cardiovascular deficiency: vasodilator. Skin deficiency: stimulates circulation.$$
WHERE id = 123;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Prickly Pear</strong> (Nopal; Opuntia spp.) is a <strong>demulcent</strong> and <strong>emollient</strong> cactus - listed as an alternative to <a href="?herb=202"><strong>Aloe</strong></a> for <strong>burns</strong>; demulcent for <strong>sore throat</strong>. Cactus fruit juice with celery for <strong>blood sugar regulation</strong>.$$
WHERE id = 2748;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Prince Seng</strong> (Pseudostellaria heterophylla) is a <strong>pulmonary tonic</strong> specific for <strong>lung tissue restoration</strong>; lung tonic alongside <a href="?herb=61"><strong>Mullein</strong></a>. For <strong>asthma</strong> and <strong>emphysema</strong>: pulmonary tonic.$$
WHERE id = 982;
